<script setup>
import {ref,onMounted,computed} from 'vue'
import {api} from './api'
import PurgeSettings from './PurgeSettings.vue'
const props=defineProps({post:Number,token:String,language:String,manageAllowed:Boolean})
const emit=defineEmits(['dirty'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const section=ref('parameters'),value=ref(null),revision=ref(''),busy=ref(false),error=ref(''),notice=ref(''),dirty=ref(false),textLang=ref('uz')
const errorText=e=>/No confirmation|Target controller unavailable/.test(e.message)?tr('Пост не подтвердил сохранение. Перечитайте настройки перед повтором.','Post saqlashni tasdiqlamadi. Qayta urinishdan oldin sozlamalarni qayta o‘qing.','Station did not confirm saving. Reload settings before retrying.'):/Settings changed/.test(e.message)?tr('Настройки уже изменены. Перечитайте их перед сохранением.','Sozlamalar o‘zgargan. Saqlashdan oldin qayta o‘qing.','Settings have changed. Reload before saving.'):e.message
const url=()=>`/api/owner/site/posts/${props.post}/${section.value}`
const request=(options={})=>api(url(),{token:props.token,...options})
const title=computed(()=>tr('Настройки поста','Post sozlamalari','Station settings')+' '+props.post)
const name=k=>({water:'SUV',foam:'KO‘PIK',wax:'MUM',chem:'KIMYO',osmos:'OSMOS',nano:'NANO',vacuum:'CHANGYUTGICH',air:'HAVO',aroma_1:'SHEIKH SULTAN',aroma_2:'BLACK ICE',aroma_3:'NARCOTIC',aroma_4:'INVICTUS CREED',aroma_5:'ANTI-TOBACCO',blackening:'SHINA QORAYTIRISH',tank_air:'SHINANI DAMLASH'}[k]||k)
const appearance=computed({get:()=>value.value?.theme?.appearance?.mode==='auto'?'auto':value.value?.theme?.appearance?.manualTheme||'dark',set:v=>{value.value.theme.appearance.mode=v==='auto'?'auto':'manual';if(v!=='auto')value.value.theme.appearance.manualTheme=v}})
function mark(){dirty.value=true;notice.value='';emit('dirty',true)}
async function load(){busy.value=true;error.value='';try{const r=await request();value.value=r.value;revision.value=r.revision;if(section.value==='kiosk')for(const p of value.value.programs)p.description||={};dirty.value=false;emit('dirty',false)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function choose(s){if(dirty.value)return;section.value=s;value.value=null;notice.value='';await load()}
async function save(){busy.value=true;error.value='';notice.value='';try{const r=await request({method:'POST',body:JSON.stringify({expected_revision:revision.value,value:value.value})});if(!r.confirmed||r.post_no!==props.post)throw Error(tr('Нет подтверждения от поста','Post tasdig‘i yo‘q','No confirmation from target'));value.value=r.value;revision.value=r.revision;dirty.value=false;emit('dirty',false);notice.value=tr('Пост подтвердил сохранение','Post saqlanganini tasdiqladi','Station confirmed saved settings')+' · '+props.post}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="site-settings card"><h2>{{title}}</h2><div class="actions"><button v-for="[key,ru,uz,en] in [['parameters','Тарифы и пауза','Tariflar va pauza','Rates and pause'],['kiosk','Экран','Ekran','Screen'],['operator','Оператор','Operator','Operator']]" :key="key" class="quiet" :class="{selected:section===key}" :disabled="busy||dirty" @click="choose(key)">{{tr(ru,uz,en)}}</button></div><p class="muted">{{tr('Изменения применяются только на выбранном свободном посту. Сохранение требует ответа этого поста.','O‘zgarishlar faqat tanlangan bo‘sh postga qo‘llanadi. Saqlash shu post javobini talab qiladi.','Changes apply only to the selected idle station. Saving requires its confirmation.')}}</p><div v-if="error" class="message error" role="alert">{{error}}</div><div v-if="notice" class="message success" role="status">{{notice}}</div>
<form v-if="value" @submit.prevent="save" @input="mark" @change="mark"><fieldset :disabled="busy||!manageAllowed"><template v-if="section==='parameters'"><div class="table-wrap"><table><thead><tr><th>{{tr('Услуга','Xizmat','Service')}}</th><th>{{tr('Сумма, сум','Summa, so‘m','Price, sum')}}</th><th>{{tr('Секунды','Soniya','Seconds')}}</th><th>{{tr('Включена','Yoqilgan','Enabled')}}</th></tr></thead><tbody><tr v-for="[key,tariff] in Object.entries(value.tariffs).filter(([key])=>key!=='pause')" :key="key"><th>{{name(key)}}</th><td><input type="number" v-model.number="tariff.amountSum" min="0" max="10000000" required :aria-label="name(key)+' '+tr('сумма','summa','price')"/></td><td><input type="number" v-model.number="tariff.durationSeconds" min="1" max="86400" required :aria-label="name(key)+' '+tr('секунды','soniya','seconds')"/></td><td><input type="checkbox" v-model="tariff.enabled" :aria-label="name(key)+' '+tr('включена','yoqilgan','enabled')"/></td></tr></tbody></table></div><div class="settings-fields"><label v-if="'pauseEnabled' in value" class="check"><input type="checkbox" v-model="value.pauseEnabled"/>{{tr('Клиентская пауза','Mijoz pauzasi','Customer pause')}}</label><label v-if="'requireTotalStopTrigger' in value&&!('aroma_1' in value.tariffs)" class="check"><input type="checkbox" v-model="value.requireTotalStopTrigger"/>{{tr('Курок / Total Stop','Pistolet tepkisi / Total Stop','Trigger / Total Stop')}}</label><label>{{tr('Бесплатная пауза, сек','Bepul pauza, soniya','Free pause, seconds')}}<input type="number" :disabled="!!value.bonusDomain" v-model.number="value.freePauseSeconds" min="0" max="86400"/></label><label class="check"><input type="checkbox" v-model="value.paidPause.enabled"/>{{tr('Платная пауза','Pullik pauza','Paid pause')}}</label><label>{{tr('Цена паузы, сум','Pauza narxi, so‘m','Pause price, sum')}}<input type="number" v-model.number="value.paidPause.amountSum" min="0" required/></label><label>{{tr('За сколько секунд','Necha soniya uchun','Per seconds')}}<input type="number" v-model.number="value.paidPause.durationSeconds" min="1" required/></label></div><PurgeSettings v-if="value.purge&&value.tariffs.aroma_1" v-model="value.purge" :language="language"/><p class="muted">{{tr('Общие бонусы и бюджеты паузы задаются в разделе «Кошелёк».','Umumiy bonus va pauza vaqti «Hamyon» bo‘limida sozlanadi.','Shared bonuses and pause budgets are configured under Wallet.')}}</p></template>
<template v-else-if="section==='kiosk'"><div class="settings-fields"><label>{{tr('Вид экрана','Ekran ko‘rinishi','Appearance')}}<select v-model="appearance"><option value="auto">Auto</option><option value="dark">Dark</option><option value="light">Light</option></select></label><template v-if="appearance==='auto'"><label>{{tr('Светлая тема с','Yorug‘ ko‘rinish boshlanishi','Light starts')}}<input type="time" v-model="value.theme.appearance.lightStart" required/></label><label>{{tr('До','Gacha','Until')}}<input type="time" v-model="value.theme.appearance.lightEnd" required/></label></template><label>{{tr('Язык текстов','Matn tili','Text language')}}<select v-model="textLang"><option v-for="l in ['uz','ru','kz','ky']" :key="l" :value="l">{{l.toUpperCase()}}</option></select></label></div><div class="settings-programs"><section v-for="p in value.programs" :key="p.id"><h3>{{name(p.id)}}</h3><label>{{tr('Название','Nomi','Name')}}<input v-model="p.label[textLang]" maxlength="80"/></label><label>{{tr('Подпись','Izoh','Subtitle')}}<input v-model="p.description[textLang]" maxlength="160"/></label><label class="check"><input type="checkbox" v-model="p.visible"/>{{tr('Показывать','Ko‘rsatish','Visible')}}</label></section></div></template>
<template v-else><div class="settings-fields"><label class="check"><input type="checkbox" v-model="value.enabled"/>{{tr('Вызов оператора','Operatorni chaqirish','Operator call')}}</label><label>{{tr('Телефон оператора','Operator telefoni','Operator phone')}}<input type="tel" v-model="value.phone" maxlength="40"/></label><label>Telegram chat ID<input v-model="value.chat_id" maxlength="21"/></label></div></template></fieldset><div class="actions"><button class="primary" :disabled="busy||!dirty||!manageAllowed">{{busy?tr('Ожидание подтверждения…','Tasdiq kutilmoqda…','Awaiting confirmation…'):tr('Сохранить на этом посту','Shu postda saqlash','Save on this station')}}</button><button type="button" class="quiet" :disabled="busy" @click="load">{{tr('Перечитать настройки','Sozlamalarni qayta o‘qish','Reload settings')}}</button></div></form></section></template>
<style scoped>
.site-settings{padding:24px;margin-top:20px}.site-settings label{display:flex;flex-direction:column;gap:8px}.site-settings label.check{flex-direction:row;align-items:center}.site-settings h2{margin-top:0}.site-settings fieldset{border:0;margin:0;padding:0;min-width:0}.settings-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:24px 0}.site-settings table input[type=number]{width:100%;min-width:80px}.site-settings .actions{display:flex;flex-wrap:wrap;gap:10px}.settings-programs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:20px 0}.settings-programs section{border:1px solid var(--border);padding:16px;border-radius:6px}.settings-programs label{margin-bottom:12px}.site-settings p{line-height:1.6}.selected{background:var(--selected);color:var(--accent)}@media(max-width:650px){.site-settings{padding:16px}.settings-fields,.settings-programs{grid-template-columns:1fr}.site-settings .actions button{font-size:14px;padding:12px}}
</style>
